#include <bits/stdc++.h>
using namespace std;using U=uint64_t;U adj[64];int N;unsigned long long visits=0;vector<int> cur,witness;
bool path(int u,int t,int rem,U seen){visits++;if(rem==1){if(adj[u]>>t&1){witness=cur;witness.push_back(t);return true;}return false;}U m=adj[u]&~seen&~(1ULL<<t);while(m){int v=__builtin_ctzll(m);m&=m-1;cur.push_back(v);if(path(v,t,rem-1,seen|(1ULL<<v)))return true;cur.pop_back();}return false;}
int main(int argc,char**argv){if(argc<3)return 2;ifstream f(argv[1]);int mode=stoi(argv[2]);string tag;int m;while(f>>tag){if(tag=="p"){string x;f>>x>>N>>m;}else if(tag=="e"){int a,b;f>>a>>b;--a;--b;adj[a]|=1ULL<<b;adj[b]|=1ULL<<a;}else{string z;getline(f,z);}}if(N>64)return 3;vector<int>ts;for(int v=0;v<N;v++)if(argc>3||__builtin_popcountll(adj[v])==2)ts.push_back(v);int tested=0,legal=0;map<int,int>blocks;for(int a:ts)for(int b:ts)if(a<b){if(mode!=2&&(adj[a]>>b&1))continue;if(mode==1&&(adj[a]&adj[b]))continue;tested++;int bad=0;for(int L=4;L<=N-(mode==1)+(mode==2);L*=2){int d=L-(mode==0)-2*(mode==2);cur={a};if(path(a,b,d,1ULL<<a)){bad=L;break;}}if(bad){blocks[bad]++;cout<<"BLOCK "<<a+1<<" "<<b+1<<" "<<bad;for(int x:witness)cout<<" "<<x+1;cout<<"\n";}else{legal++;cout<<"LEGAL "<<a+1<<" "<<b+1<<"\n";}}cerr<<"n "<<N<<" mode "<<mode<<" tested "<<tested<<" legal "<<legal<<" DFSstates "<<visits;for(auto[k,v]:blocks)cerr<<" C"<<k<<":"<<v;cerr<<"\n";}
